export const TWS_LINK_POLICY: { readonly utmOnOwnedLinks: boolean; readonly utmMedium: string } = {
  "utmOnOwnedLinks": false,
  "utmMedium": "referral"
};

export type TwsFamilyProperty = (typeof TWS_FAMILY_PROPERTIES)[number];
export type TwsFamilyPropertyKey = TwsFamilyProperty['key'];
export type TwsFamilyGroupKey = (typeof TWS_FAMILY_GROUPS)[number]['key'];

export interface TwsFamilyStripGroup {
  key: TwsFamilyGroupKey;
  label: string;
  items: TwsFamilyProperty[];
}

/** Family links grouped for a footer strip. Pass the keys of the site that
 *  renders the strip so it does not link to itself. Only entries marked
 *  strip: true in the registry appear, in registry order. */
export function familyStrip(exclude: readonly TwsFamilyPropertyKey[] = []): TwsFamilyStripGroup[] {
  return TWS_FAMILY_GROUPS.map((group) => ({
    key: group.key,
    label: group.label,
    items: TWS_FAMILY_PROPERTIES.filter(
      (p) => p.strip && p.group === group.key && !exclude.includes(p.key),
    ),
  })).filter((group) => group.items.length > 0);
}

/** The href for a link to another family site. Follows the registry switch
 *  linkPolicy.utmOnOwnedLinks, so the whole family changes UTM behaviour in
 *  one place. source is the site that renders the link (for example "blog"),
 *  campaign the placement (for example "family_strip"). */
export function familyHref(url: string, source: string, campaign: string): string {
  if (!TWS_LINK_POLICY.utmOnOwnedLinks) return url;
  const sep = url.includes('?') ? '&' : '?';
  return `${url}${sep}utm_source=${encodeURIComponent(source)}&utm_medium=${TWS_LINK_POLICY.utmMedium}&utm_campaign=${encodeURIComponent(campaign)}`;
}

/** Looks a family property up by key. */
export function familyProperty(key: TwsFamilyPropertyKey): TwsFamilyProperty {
  const found = TWS_FAMILY_PROPERTIES.find((p) => p.key === key);
  if (!found) throw new Error(`Unknown family property: ${key}`);
  return found;
}

/** The parent Organization node. Identical on every family site, so search
 *  engines can merge the sites into one entity through the shared @id. */
export function familyOrganizationJsonLd() {
  return {
    '@type': 'Organization',
    '@id': TWS_ORGANIZATION.id,
    name: TWS_ORGANIZATION.name,
    legalName: TWS_ORGANIZATION.legalName,
    url: TWS_ORGANIZATION.url,
    logo: { '@type': 'ImageObject', url: TWS_ORGANIZATION.logo },
    sameAs: TWS_SOCIALS.map((s) => s.url),
    founder: { '@id': TWS_FOUNDER.id },
  };
}

/** The founder Person node, shared by @id across the family. */
export function familyFounderJsonLd() {
  return {
    '@type': 'Person',
    '@id': TWS_FOUNDER.id,
    name: TWS_FOUNDER.name,
    jobTitle: TWS_FOUNDER.jobTitle,
    url: TWS_FOUNDER.url,
    image: TWS_FOUNDER.image,
    worksFor: { '@id': TWS_ORGANIZATION.id },
  };
}

/** A complete JSON-LD graph for one family site: the parent Organization, the
 *  founder, and this site's WebSite node published by the parent. Pass extra
 *  nodes (a sub-brand Organization, a SoftwareApplication) through extraNodes. */
export function familyJsonLdGraph(site: { url: string; name: string }, extraNodes: object[] = []) {
  const siteUrl = site.url.replace(/\/+$/, '');
  return {
    '@context': 'https://schema.org',
    '@graph': [
      familyOrganizationJsonLd(),
      familyFounderJsonLd(),
      {
        '@type': 'WebSite',
        '@id': `${siteUrl}/#website`,
        url: siteUrl,
        name: site.name,
        publisher: { '@id': TWS_ORGANIZATION.id },
      },
      ...extraNodes,
    ],
  };
}

/** Records a click on a link to another family site. GTM forwards every
 *  dataLayer event to GA4, so this needs no container change. Safe to call
 *  during server rendering (it does nothing there). */
export function trackFamilyLinkClick(href: string, placement: string, source: string): void {
  if (typeof window === 'undefined') return;
  let domain: string;
  try {
    domain = new URL(href).hostname;
  } catch {
    return;
  }
  const w = window as unknown as { dataLayer?: Record<string, unknown>[] };
  w.dataLayer = w.dataLayer || [];
  w.dataLayer.push({
    event: TWS_TRACKING.clickEvent,
    link_url: href,
    link_domain: domain,
    link_placement: placement,
    family_source: source,
  });
}
